export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let queue = [];

  try {
    const stored = storage.getItem(key);

    if (stored !== null) {
      const parsed = JSON.parse(stored);

      if (Array.isArray(parsed)) {
        queue = parsed.map((item) => ({
          id: item.id,
          type: item.type,
          payload: item.payload,
          dedupeKey: item.dedupeKey,
          attempts:
            typeof item.attempts === "number" ? item.attempts : 0,
        }));
      }
    }
  } catch {
    queue = [];
  }

  let inFlight = null;
  let activeFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(queue));
  }

  function enqueue(action) {
    if (queue.some((item) => item.id === action.id)) {
      return undefined;
    }

    if (action.dedupeKey !== undefined) {
      const existing = queue.find(
        (item) =>
          item !== inFlight && item.dedupeKey === action.dedupeKey,
      );

      if (existing) {
        existing.type = action.type;
        existing.payload = action.payload;
        existing.attempts = 0;
        persist();
        return undefined;
      }
    }

    queue.push({
      id: action.id,
      type: action.type,
      payload: action.payload,
      dedupeKey: action.dedupeKey,
      attempts: 0,
    });

    persist();
    return undefined;
  }

  function size() {
    return queue.length;
  }

  function peek() {
    return queue.map((item) => ({
      id: item.id,
      type: item.type,
      payload: item.payload,
      dedupeKey: item.dedupeKey,
      attempts: item.attempts,
    }));
  }

  async function executeFlush(
    publicPromise,
    resolvePublic,
    rejectPublic,
  ) {
    try {
      const sent = [];
      const failed = [];

      while (queue.length > 0) {
        const current = queue[0];
        let outcome = "retryable";

        inFlight = current;

        try {
          const response = await send({
            id: current.id,
            type: current.type,
            payload: current.payload,
          });

          if (response !== null && response !== undefined) {
            const ok = response.ok;

            if (ok === true) {
              outcome = "success";
            } else if (
              ok === false &&
              response.retryable === false
            ) {
              outcome = "permanent";
            }
          }
        } catch {
          outcome = "retryable";
        } finally {
          inFlight = null;
        }

        if (outcome === "success") {
          queue.shift();
          persist();
          sent.push(current.id);
          continue;
        }

        if (outcome === "permanent") {
          queue.shift();
          persist();
          failed.push({ id: current.id, reason: "rejected" });
          continue;
        }

        const attempts =
          (typeof current.attempts === "number"
            ? current.attempts
            : 0) + 1;

        current.attempts = attempts;
        persist();

        if (attempts >= maxAttempts) {
          queue.shift();
          persist();
          failed.push({
            id: current.id,
            reason: "max-attempts",
          });
        }

        break;
      }

      const result = {
        sent,
        failed,
        remaining: queue.length,
      };

      if (activeFlush === publicPromise) {
        activeFlush = null;
      }

      resolvePublic(result);
    } catch (error) {
      inFlight = null;

      if (activeFlush === publicPromise) {
        activeFlush = null;
      }

      rejectPublic(error);
    }
  }

  function flush() {
    if (activeFlush !== null) {
      return activeFlush;
    }

    let resolvePublic;
    let rejectPublic;

    const publicPromise = new Promise((resolve, reject) => {
      resolvePublic = resolve;
      rejectPublic = reject;
    });

    activeFlush = publicPromise;
    executeFlush(publicPromise, resolvePublic, rejectPublic);

    return publicPromise;
  }

  return {
    enqueue,
    flush,
    size,
    peek,
  };
}
